WITH metrics AS (SELECT id, city, region, FIRST_VALUE(sqft) IGNORE NULLS OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_sqft, SUM(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft, ROUND(sqft / SUM(sqft) OVER (PARTITION BY city), 4) AS sqft_share, SUM(sqft) OVER w_ordered AS region_sum_sqft FROM stores WINDOW w_ordered AS (PARTITION BY region)) SELECT city, PERCENTILE_APPROX(running_sqft, ARRAY(0.25, 0.5, 0.75)) AS running_sqft_quartiles, COUNT(*) FILTER (WHERE city = 'Tokyo') AS tokyo_rows, SIZE(COLLECT_SET(city)) AS num_cities, COUNT(DISTINCT region) AS distinct_regions, SUM(CASE WHEN city = 'Singapore' THEN sqft_share ELSE 0 END) AS singapore_sqft_share FROM metrics GROUP BY 1 ORDER BY tokyo_rows DESC;
